import React, { useState, useEffect } from 'react';
import { Sun, Moon, Globe, Menu, X, ChevronDown, User, LogIn, UserPlus, Brain, Home, BookOpen, BarChart, Shield } from 'lucide-react';
import { Link, useNavigate } from 'react-router-dom';
import { useTranslation } from '../';

// Traductions spécifiques pour Mpanolo-tsaina AI
const headerTranslations = {
  en: {
    home: 'Home',
    check: 'Verify Content',
    dashboard: 'Dashboard',
    learn: 'Learn',
    about: 'About',
    language: 'Language',
    theme: 'Theme',
    light: 'Light',
    dark: 'Dark',
    system: 'System',
    login: 'Login',
    register: 'Register',
    profile: 'Profile',
    logout: 'Logout',
    welcome: 'Welcome',
    getStarted: 'Get Started',
    analytics: 'Analytics',
    literacy: 'Media Literacy',
    offlineMode: 'Offline Mode',
    verifiedContent: 'Verified Content',
    factChecking: 'Fact Checking',
    trustScore: 'Trust Score'
  },
  fr: {
    home: 'Accueil',
    check: 'Vérifier Contenu',
    dashboard: 'Tableau de Bord',
    learn: 'Apprendre',
    about: 'À Propos',
    language: 'Langue',
    theme: 'Thème',
    light: 'Clair',
    dark: 'Sombre',
    system: 'Système',
    login: 'Connexion',
    register: 'Inscription',
    profile: 'Profil',
    logout: 'Déconnexion',
    welcome: 'Bienvenue',
    getStarted: 'Commencer',
    analytics: 'Analytiques',
    literacy: 'Littératie Médiatique',
    offlineMode: 'Mode Hors Ligne',
    verifiedContent: 'Contenu Vérifié',
    factChecking: 'Vérification des Faits',
    trustScore: 'Score de Confiance'
  },
  mg: {
    home: 'Fandraisana',
    check: 'Hamarinina',
    dashboard: 'Tabilao',
    learn: 'Fianarana',
    about: 'Momba',
    language: 'Fiteny',
    theme: 'Teny',
    light: 'Mazava',
    dark: 'Maizina',
    system: 'Rafitra',
    login: 'Hiditra',
    register: 'Hisoratra',
    profile: 'Profil',
    logout: 'Hivoaka',
    welcome: 'Tonga soa',
    getStarted: 'Atombohy',
    analytics: 'Fandinihana',
    literacy: 'Fahaizana mamaky ny media',
    offlineMode: 'Miala tambiny',
    verifiedContent: 'Vaovao voamarina',
    factChecking: 'Fahamarinan\'ny vaovao',
    trustScore: 'Vidim-pitokisana'
  },
};

const Header = ({ isAuthenticated = false, onLogout, userData = null }) => {
  const navigate = useNavigate();
  const { t: appT, language: appLanguage, setLanguage: setAppLanguage } = useTranslation();

  // États
  const [language, setLanguage] = useState(appLanguage);
  const [darkMode, setDarkMode] = useState(false);
  const [mobileMenuOpen, setMobileMenuOpen] = useState(false);
  const [languageDropdownOpen, setLanguageDropdownOpen] = useState(false);
  const [themeDropdownOpen, setThemeDropdownOpen] = useState(false);
  const [userDropdownOpen, setUserDropdownOpen] = useState(false);
  const [isOnline, setIsOnline] = useState(navigator.onLine);

  // Récupérer les données utilisateur
  const userEmail = userData?.email || localStorage.getItem('userEmail') || '';
  const userName = userData?.name || userEmail.split('@')[0] || 'User';

  // Navigation items pour Mpanolo-tsaina AI
  const navItems = [
    { key: 'home', icon: Home, path: '/' },
    { key: 'check', icon: Shield, path: '/check' },
    { key: 'learn', icon: BookOpen, path: '/learn' },
    { key: 'dashboard', icon: BarChart, path: '/dashboard' }
  ];

  // Initialiser le thème et la langue
  useEffect(() => {
    // Thème
    const storedTheme = localStorage.getItem('theme');
    const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;

    if (storedTheme === 'dark' || (!storedTheme && systemPrefersDark)) {
      setDarkMode(true);
      document.documentElement.classList.add('dark');
    } else {
      document.documentElement.classList.remove('dark');
    }

    // Langue
    const savedLanguage = localStorage.getItem('language') || 'mg';
    setLanguage(savedLanguage);
    setAppLanguage(savedLanguage);

    // Vérifier la connexion
    const updateOnlineStatus = () => setIsOnline(navigator.onLine);
    window.addEventListener('online', updateOnlineStatus);
    window.addEventListener('offline', updateOnlineStatus);

    return () => {
      window.removeEventListener('online', updateOnlineStatus);
      window.removeEventListener('offline', updateOnlineStatus);
    };
  }, [setAppLanguage]);

  // Changer le mode sombre/clair
  const toggleDarkMode = () => {
    const newDarkMode = !darkMode;
    setDarkMode(newDarkMode);

    if (newDarkMode) {
      document.documentElement.classList.add('dark');
      localStorage.setItem('theme', 'dark');
    } else {
      document.documentElement.classList.remove('dark');
      localStorage.setItem('theme', 'light');
    }
  };

  // Changer de langue
  const changeLanguage = (lang) => {
    setLanguage(lang);
    setAppLanguage(lang);
    localStorage.setItem('language', lang);
    setLanguageDropdownOpen(false);
  };

  // Changer le thème
  const changeTheme = (theme) => {
    if (theme === 'system') {
      localStorage.removeItem('theme');
      const systemPrefersDark = window.matchMedia('(prefers-color-scheme: dark)').matches;
      setDarkMode(systemPrefersDark);
      if (systemPrefersDark) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    } else {
      const newDarkMode = theme === 'dark';
      setDarkMode(newDarkMode);
      localStorage.setItem('theme', theme);
      if (newDarkMode) {
        document.documentElement.classList.add('dark');
      } else {
        document.documentElement.classList.remove('dark');
      }
    }
    setThemeDropdownOpen(false);
  };

  // Navigation
  const handleLoginClick = () => {
    navigate('/login');
    setMobileMenuOpen(false);
  };

  const handleRegisterClick = () => {
    navigate('/register');
    setMobileMenuOpen(false);
  };

  const handleLogout = () => {
    if (onLogout) {
      onLogout();
    }
    setUserDropdownOpen(false);
    setMobileMenuOpen(false);
    navigate('/');
  };

  // Obtenir le texte traduit pour le header
  const t = (key) => headerTranslations[language][key] || key;

  // Obtenir le label pour l'indicateur hors ligne
  const getOfflineLabel = () => {
    if (!isOnline) {
      return language === 'mg' ? 'Miala tambiny' : 
             language === 'fr' ? 'Hors ligne' : 
             'Offline';
    }
    return '';
  };

  return (
    <header className="sticky top-0 z-50 w-full border-b border-gray-200 dark:border-gray-800 bg-white/95 dark:bg-gray-900/95 backdrop-blur-md transition-colors duration-300 shadow-sm">
      <div className="container mx-auto px-4 sm:px-6 lg:px-8">
        <div className="flex items-center justify-between h-16">

          {/* Logo Mpanolo-tsaina AI */}
          <Link to="/" className="flex items-center space-x-3">
            <div className="h-10 w-10 rounded-full bg-gradient-to-r from-blue-500 to-green-500 flex items-center justify-center">
              <Brain size={24} className="text-white" />
            </div>
            <div className="flex flex-col">
              <span className="text-xl font-bold text-gray-900 dark:text-white">
                Mpanolo<span className="text-blue-600 dark:text-blue-400">-tsaina</span>
              </span>
              <span className="text-xs text-gray-600 dark:text-gray-400 font-medium">
                {t('factChecking')}
              </span>
            </div>
          </Link>

          {/* Navigation Desktop */}
          <nav className="hidden md:flex items-center space-x-1">
            {navItems.map((item) => (
              <Link
                key={item.key}
                to={item.path}
                className="flex items-center space-x-2 px-4 py-2 rounded-lg text-gray-700 dark:text-gray-300 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-all duration-200 font-medium"
              >
                <item.icon size={18} />
                <span>{t(item.key)}</span>
              </Link>
            ))}
          </nav>

          {/* Actions: Indicateur hors ligne, Langue, Thème, Authentification */}
          <div className="flex items-center space-x-2">

            {/* Indicateur de mode hors ligne */}
            {!isOnline && (
              <div className="hidden sm:flex items-center px-3 py-1.5 rounded-full bg-yellow-100 dark:bg-yellow-900/30 border border-yellow-200 dark:border-yellow-800">
                <div className="h-2 w-2 rounded-full bg-yellow-500 animate-pulse mr-2"></div>
                <span className="text-xs font-medium text-yellow-800 dark:text-yellow-200">
                  {getOfflineLabel()}
                </span>
              </div>
            )}

            {/* Sélecteur de langue */}
            <div className="relative">
              <button
                onClick={() => {
                  setLanguageDropdownOpen(!languageDropdownOpen);
                  setThemeDropdownOpen(false);
                  setUserDropdownOpen(false);
                }}
                className="flex items-center space-x-1 px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors"
                aria-label={t('language')}
              >
                <Globe size={18} className="text-gray-600 dark:text-gray-400" />
                <span className="font-medium text-gray-700 dark:text-gray-300">
                  {language === 'en' ? 'EN' : language === 'fr' ? 'FR' : 'MG'}
                </span>
                <ChevronDown size={16} className="text-gray-500" />
              </button>

              {/* Dropdown langue */}
              {languageDropdownOpen && (
                <div className="absolute right-0 mt-2 w-44 py-2 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-lg shadow-lg z-50">
                  <button
                    onClick={() => changeLanguage('mg')}
                    className={`w-full text-left px-4 py-2 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors ${language === 'mg' ? 'text-blue-600 dark:text-blue-400 font-medium' : 'text-gray-700 dark:text-gray-300'}`}
                  >
                    <div className="flex items-center space-x-3">
                      <span className="text-base">🇲🇬</span>
                      <div className="flex flex-col items-start">
                        <span>Malagasy</span>
                        <span className="text-xs text-gray-500 dark:text-gray-400">Mpanolo-tsaina</span>
                      </div>
                    </div>
                  </button>
                  <button
                    onClick={() => changeLanguage('fr')}
                    className={`w-full text-left px-4 py-2 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors ${language === 'fr' ? 'text-blue-600 dark:text-blue-400 font-medium' : 'text-gray-700 dark:text-gray-300'}`}
                  >
                    <div className="flex items-center space-x-3">
                      <span className="text-base">🇫🇷</span>
                      <div className="flex flex-col items-start">
                        <span>Français</span>
                        <span className="text-xs text-gray-500 dark:text-gray-400">Mpanolo-tsaina</span>
                      </div>
                    </div>
                  </button>
                  <button
                    onClick={() => changeLanguage('en')}
                    className={`w-full text-left px-4 py-2 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors ${language === 'en' ? 'text-blue-600 dark:text-blue-400 font-medium' : 'text-gray-700 dark:text-gray-300'}`}
                  >
                    <div className="flex items-center space-x-3">
                      <span className="text-base">🇺🇸</span>
                      <div className="flex flex-col items-start">
                        <span>English</span>
                        <span className="text-xs text-gray-500 dark:text-gray-400">Mpanolo-tsaina AI</span>
                      </div>
                    </div>
                  </button>
                </div>
              )}
            </div>

            {/* Sélecteur de thème */}
            <div className="relative hidden sm:block">
              <button
                onClick={() => {
                  setThemeDropdownOpen(!themeDropdownOpen);
                  setLanguageDropdownOpen(false);
                  setUserDropdownOpen(false);
                }}
                className="flex items-center space-x-1 px-3 py-2 rounded-lg border border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors"
                aria-label={t('theme')}
              >
                {darkMode ? (
                  <Moon size={18} className="text-gray-600 dark:text-gray-400" />
                ) : (
                  <Sun size={18} className="text-gray-600 dark:text-gray-400" />
                )}
                <ChevronDown size={16} className="text-gray-500" />
              </button>

              {/* Dropdown thème */}
              {themeDropdownOpen && (
                <div className="absolute right-0 mt-2 w-44 py-2 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-lg shadow-lg z-50">
                  <button
                    onClick={() => changeTheme('light')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors text-gray-700 dark:text-gray-300"
                  >
                    <Sun size={16} className="text-yellow-500" />
                    <div className="flex flex-col items-start">
                      <span>{t('light')}</span>
                      <span className="text-xs text-gray-500 dark:text-gray-400">{appT('lightMode') || 'Light mode'}</span>
                    </div>
                  </button>
                  <button
                    onClick={() => changeTheme('dark')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors text-gray-700 dark:text-gray-300"
                  >
                    <Moon size={16} className="text-blue-400" />
                    <div className="flex flex-col items-start">
                      <span>{t('dark')}</span>
                      <span className="text-xs text-gray-500 dark:text-gray-400">{appT('darkMode') || 'Dark mode'}</span>
                    </div>
                  </button>
                  <button
                    onClick={() => changeTheme('system')}
                    className="w-full text-left px-4 py-2 flex items-center space-x-3 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors text-gray-700 dark:text-gray-300"
                  >
                    <div className="flex items-center">
                      <Sun size={14} className="mr-[-2px] text-yellow-500" />
                      <Moon size={14} className="ml-[-2px] text-blue-400" />
                    </div>
                    <div className="flex flex-col items-start">
                      <span>{t('system')}</span>
                      <span className="text-xs text-gray-500 dark:text-gray-400">{appT('systemMode') || 'System preference'}</span>
                    </div>
                  </button>
                </div>
              )}
            </div>

            {/* Bouton mode sombre/clair (version simple pour mobile) */}
            <button
              onClick={toggleDarkMode}
              className="sm:hidden p-2 rounded-lg border border-gray-200 dark:border-gray-800 bg-white dark:bg-gray-900 hover:bg-gray-50 dark:hover:bg-gray-800 transition-colors"
              aria-label={t('theme')}
            >
              {darkMode ? (
                <Moon size={20} className="text-gray-600 dark:text-gray-400" />
              ) : (
                <Sun size={20} className="text-gray-600 dark:text-gray-400" />
              )}
            </button>

            {/* Menu mobile burger */}
            <button
              onClick={() => setMobileMenuOpen(!mobileMenuOpen)}
              className="md:hidden p-2 rounded-lg text-gray-700 dark:text-gray-300 hover:bg-gray-100 dark:hover:bg-gray-800"
              aria-label="Menu"
            >
              {mobileMenuOpen ? <X size={24} /> : <Menu size={24} />}
            </button>

            {/* Boutons d'authentification ou profil utilisateur */}
            {isAuthenticated ? (
              <div className="relative hidden md:block">
                <button
                  onClick={() => {
                    setUserDropdownOpen(!userDropdownOpen);
                    setLanguageDropdownOpen(false);
                    setThemeDropdownOpen(false);
                  }}
                  className="flex items-center space-x-2 px-4 py-2 rounded-lg bg-gradient-to-r from-blue-500 to-green-500 hover:from-blue-600 hover:to-green-600 text-white font-medium transition-all duration-300 hover:shadow-lg hover:shadow-blue-500/25"
                >
                  <div className="h-6 w-6 rounded-full bg-white/30 flex items-center justify-center">
                    <span className="text-xs font-bold">{userName.charAt(0).toUpperCase()}</span>
                  </div>
                  <span className="text-sm">{userName}</span>
                  <ChevronDown size={16} />
                </button>

                {/* Dropdown utilisateur */}
                {userDropdownOpen && (
                  <div className="absolute right-0 mt-2 w-56 py-2 bg-white dark:bg-gray-900 border border-gray-200 dark:border-gray-800 rounded-lg shadow-lg z-50">
                    <div className="px-4 py-3 border-b border-gray-200 dark:border-gray-800 bg-gradient-to-r from-blue-50 to-green-50 dark:from-blue-900/10 dark:to-green-900/10">
                      <p className="text-sm font-medium text-gray-900 dark:text-white">{userName}</p>
                      <p className="text-xs text-gray-600 dark:text-gray-400 truncate">{userEmail}</p>
                    </div>
                    <Link
                      to="/dashboard"
                      className="flex items-center space-x-3 px-4 py-2.5 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors text-gray-700 dark:text-gray-300"
                      onClick={() => setUserDropdownOpen(false)}
                    >
                      <BarChart size={16} />
                      <span>{t('dashboard')}</span>
                    </Link>
                    <Link
                      to="/profile"
                      className="flex items-center space-x-3 px-4 py-2.5 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors text-gray-700 dark:text-gray-300"
                      onClick={() => setUserDropdownOpen(false)}
                    >
                      <User size={16} />
                      <span>{t('profile')}</span>
                    </Link>
                    <div className="border-t border-gray-200 dark:border-gray-800 mt-1 pt-1">
                      <button
                        onClick={handleLogout}
                        className="w-full text-left flex items-center space-x-3 px-4 py-2.5 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors text-red-600 dark:text-red-400"
                      >
                        <LogIn size={16} />
                        <span>{t('logout')}</span>
                      </button>
                    </div>
                  </div>
                )}
              </div>
            ) : (
              <div className="hidden md:flex items-center space-x-2">
                <button
                  onClick={handleLoginClick}
                  className="flex items-center space-x-2 px-4 py-2 rounded-lg border border-blue-500 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                >
                  <LogIn size={18} />
                  <span>{t('login')}</span>
                </button>
                <button
                  onClick={handleRegisterClick}
                  className="flex items-center space-x-2 px-4 py-2 rounded-lg bg-gradient-to-r from-blue-500 to-green-500 hover:from-blue-600 hover:to-green-600 text-white font-medium transition-all duration-300 hover:shadow-lg hover:shadow-blue-500/25"
                >
                  <UserPlus size={18} />
                  <span>{t('register')}</span>
                </button>
              </div>
            )}
          </div>
        </div>

        {/* Menu Mobile */}
        {mobileMenuOpen && (
          <div className="md:hidden py-4 border-t border-gray-200 dark:border-gray-800 animate-slide-up">
            <div className="flex flex-col space-y-2">
              {/* Navigation mobile */}
              {navItems.map((item) => (
                <Link
                  key={item.key}
                  to={item.path}
                  className="flex items-center space-x-3 px-4 py-3 rounded-lg text-gray-700 dark:text-gray-300 hover:text-blue-600 dark:hover:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-all duration-200 font-medium"
                  onClick={() => setMobileMenuOpen(false)}
                >
                  <item.icon size={20} />
                  <span>{t(item.key)}</span>
                </Link>
              ))}

              {/* Indicateur hors ligne mobile */}
              {!isOnline && (
                <div className="flex items-center px-4 py-3 rounded-lg bg-yellow-50 dark:bg-yellow-900/20 border border-yellow-200 dark:border-yellow-800">
                  <div className="h-2 w-2 rounded-full bg-yellow-500 animate-pulse mr-3"></div>
                  <div className="flex flex-col">
                    <span className="text-sm font-medium text-yellow-800 dark:text-yellow-200">
                      {getOfflineLabel()}
                    </span>
                    <span className="text-xs text-yellow-700 dark:text-yellow-300">
                      {language === 'mg' ? 'Mampiasa ny angon-drakitra voatahiry' : 
                       language === 'fr' ? 'Utilisation des données en cache' : 
                       'Using cached data'}
                    </span>
                  </div>
                </div>
              )}

              {/* Séparateur */}
              <div className="border-t border-gray-200 dark:border-gray-800 pt-2">

                {/* Boutons d'authentification pour mobile */}
                {!isAuthenticated ? (
                  <div className="flex flex-col space-y-2">
                    <button
                      onClick={handleLoginClick}
                      className="flex items-center justify-center space-x-2 px-4 py-3 rounded-lg border border-blue-500 text-blue-600 dark:text-blue-400 hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                    >
                      <LogIn size={20} />
                      <span className="font-medium">{t('login')}</span>
                    </button>
                    <button
                      onClick={handleRegisterClick}
                      className="flex items-center justify-center space-x-2 px-4 py-3 rounded-lg bg-gradient-to-r from-blue-500 to-green-500 hover:from-blue-600 hover:to-green-600 text-white font-medium transition-all duration-300"
                    >
                      <UserPlus size={20} />
                      <span className="font-medium">{t('register')}</span>
                    </button>
                  </div>
                ) : (
                  <div className="space-y-2">
                    <div className="px-4 py-3 bg-gradient-to-r from-blue-50 to-green-50 dark:from-blue-900/10 dark:to-green-900/10 rounded-lg">
                      <p className="text-sm font-medium text-gray-900 dark:text-white">{userName}</p>
                      <p className="text-xs text-gray-600 dark:text-gray-400 truncate">{userEmail}</p>
                    </div>
                    <Link
                      to="/dashboard"
                      className="flex items-center space-x-3 px-4 py-3 rounded-lg hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors text-gray-700 dark:text-gray-300"
                      onClick={() => setMobileMenuOpen(false)}
                    >
                      <BarChart size={20} />
                      <span className="font-medium">{t('dashboard')}</span>
                    </Link>
                    <Link
                      to="/profile"
                      className="flex items-center space-x-3 px-4 py-3 rounded-lg hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors text-gray-700 dark:text-gray-300"
                      onClick={() => setMobileMenuOpen(false)}
                    >
                      <User size={20} />
                      <span className="font-medium">{t('profile')}</span>
                    </Link>
                    <button
                      onClick={handleLogout}
                      className="w-full flex items-center justify-center space-x-3 px-4 py-3 rounded-lg border border-red-500 text-red-600 dark:text-red-400 hover:bg-red-50 dark:hover:bg-red-900/20 transition-colors"
                    >
                      <LogIn size={20} />
                      <span className="font-medium">{t('logout')}</span>
                    </button>
                  </div>
                )}

                {/* Options de thème pour mobile */}
                <div className="pt-4 border-t border-gray-200 dark:border-gray-800">
                  <div className="flex flex-col space-y-2">
                    <div className="px-4 py-2 text-sm font-medium text-gray-500 dark:text-gray-400">
                      {t('theme')}
                    </div>
                    <button
                      onClick={() => changeTheme('light')}
                      className="flex items-center space-x-3 px-4 py-2 rounded-lg hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                    >
                      <Sun size={20} className="text-yellow-500" />
                      <span className="text-gray-700 dark:text-gray-300">{t('light')}</span>
                    </button>
                    <button
                      onClick={() => changeTheme('dark')}
                      className="flex items-center space-x-3 px-4 py-2 rounded-lg hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                    >
                      <Moon size={20} className="text-blue-400" />
                      <span className="text-gray-700 dark:text-gray-300">{t('dark')}</span>
                    </button>
                    <button
                      onClick={() => changeTheme('system')}
                      className="flex items-center space-x-3 px-4 py-2 rounded-lg hover:bg-blue-50 dark:hover:bg-blue-900/20 transition-colors"
                    >
                      <div className="flex items-center">
                        <Sun size={16} className="mr-[-2px] text-yellow-500" />
                        <Moon size={16} className="ml-[-2px] text-blue-400" />
                      </div>
                      <span className="text-gray-700 dark:text-gray-300">{t('system')}</span>
                    </button>
                  </div>
                </div>
              </div>
            </div>
          </div>
        )}
      </div>
    </header>
  );
};

// Styles CSS pour l'animation
const styles = `
@keyframes slide-up {
  from {
    opacity: 0;
    transform: translateY(-10px);
  }
  to {
    opacity: 1;
    transform: translateY(0);
  }
}

.animate-slide-up {
  animation: slide-up 0.2s ease-out;
}

@keyframes pulse {
  0%, 100% {
    opacity: 1;
  }
  50% {
    opacity: 0.5;
  }
}

.animate-pulse {
  animation: pulse 2s cubic-bezier(0.4, 0, 0.6, 1) infinite;
}
`;

// Ajouter les styles au document
if (typeof document !== 'undefined') {
  const styleSheet = document.createElement("style");
  styleSheet.innerText = styles;
  document.head.appendChild(styleSheet);
}

export default Header;
